    // Check if the start node is null
    if (start == null) {
        throw new IllegalArgumentException("Start node cannot be null");
    }

    // Check if the stop node is null
    if (stop == null) {
        throw new IllegalArgumentException("Stop node cannot be null");
    }

    // Check if the predicate is null
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate cannot be null");
    }

    // Initialize the current node to the start node
    Node currentNode = start;

    // Traverse the graph in the specified direction
    while (currentNode != null) {
        // Check if the current node satisfies the predicate
        if (predicate.test(currentNode)) {
            // Return a circulator to the current node
            return new OuterFaceCirculator(currentNode);
        }

        // Move to the next node based on the direction
        if (dir == 1) {
            currentNode = currentNode.getNext();
        } else if (dir == -1) {
            currentNode = currentNode.getPrevious();
        } else {
            throw new IllegalArgumentException("Invalid direction");
        }
    }

    // Return a circulator to the stop node
    return new OuterFaceCirculator(stop);
}

